import hashlib
import hmac
import json
import os
import struct
import tempfile
from dataclasses import dataclass, field
from typing import Any, Dict, Optional


def _load_signing_key() -> str:
    """Load the application signing key from the environment.

    Refuses to fall back to a predictable/hardcoded default, since the HMAC
    is the sole integrity boundary for serialized documents.
    """
    key = os.environ.get('APP_SECRET')
    if not key or len(key) < 32:
        raise RuntimeError(
            'APP_SECRET environment variable must be set to a strong secret '
            '(at least 32 characters). Refusing to start with a weak or missing key.'
        )
    return key


SECRET_KEY = _load_signing_key()

@dataclass
class UserSession:
    user_id: int
    role: str
    permissions: list = field(default_factory=list)

@dataclass
class DocumentMeta:
    doc_id: int
    owner_id: int
    title: str
    access_level: str = "private"

class SecureSerializer:
    """Custom binary serialization with HMAC integrity verification."""

    MAGIC = b'SDOC'
    VERSION = 1

    def __init__(self, signing_key: str):
        self._key = signing_key.encode('utf-8')

    def _compute_mac(self, data: bytes) -> bytes:
        return hmac.new(self._key, data, hashlib.sha256).digest()

    def serialize_document(self, meta: DocumentMeta, content: bytes) -> bytes:
        header = self.MAGIC + struct.pack('<BII', self.VERSION, meta.doc_id, meta.owner_id)
        title_bytes = meta.title.encode('utf-8')
        header += struct.pack('<H', len(title_bytes)) + title_bytes
        access_bytes = meta.access_level.encode('utf-8')
        header += struct.pack('<B', len(access_bytes)) + access_bytes
        payload = header + struct.pack('<I', len(content)) + content
        mac = self._compute_mac(payload)
        return payload + mac

    def deserialize_document(self, data: bytes) -> tuple:
        if len(data) < 4 + 1 + 4 + 4 + 32:
            raise ValueError("Data too short")

        mac_received = data[-32:]
        payload = data[:-32]
        mac_computed = self._compute_mac(payload)

        if not hmac.compare_digest(mac_received, mac_computed):
            raise ValueError("Integrity check failed")

        offset = 0
        magic = payload[offset:offset+4]
        if magic != self.MAGIC:
            raise ValueError("Invalid magic bytes")
        offset += 4

        version, doc_id, owner_id = struct.unpack_from('<BII', payload, offset)
        offset += 9

        title_len = struct.unpack_from('<H', payload, offset)[0]
        offset += 2
        title = payload[offset:offset+title_len].decode('utf-8')
        offset += title_len

        access_len = struct.unpack_from('<B', payload, offset)[0]
        offset += 1
        access_level = payload[offset:offset+access_len].decode('utf-8')
        offset += access_len

        content_len = struct.unpack_from('<I', payload, offset)[0]
        offset += 4
        content = payload[offset:offset+content_len]

        meta = DocumentMeta(doc_id=doc_id, owner_id=owner_id, title=title, access_level=access_level)
        return meta, content


class DocumentStore:
    """Manages document storage with access control."""

    def __init__(self):
        self._store: Dict[int, bytes] = {}
        self._serializer = SecureSerializer(SECRET_KEY)

    def upload_document(self, session: UserSession, title: str, content: bytes) -> int:
        doc_id = len(self._store) + 1
        meta = DocumentMeta(doc_id=doc_id, owner_id=session.user_id, title=title)
        serialized = self._serializer.serialize_document(meta, content)
        self._store[doc_id] = serialized
        return doc_id

    def get_document(self, session: UserSession, doc_id: int) -> Optional[tuple]:
        if doc_id not in self._store:
            return None

        meta, content = self._serializer.deserialize_document(self._store[doc_id])

        if not self._check_access(session, meta):
            return None

        return meta, content

    def import_document(self, session: UserSession, raw_data: bytes) -> Optional[int]:
        """Import a previously exported document from untrusted upload.

        Security: imported documents are always set to 'private' access
        regardless of what the serialized data claims, and ownership is
        reassigned to the importing user.
        """
        try:
            meta, content = self._serializer.deserialize_document(raw_data)
        except (ValueError, struct.error):
            return None

        # Re-assign ownership and force private access for imported documents
        new_meta = DocumentMeta(
            doc_id=len(self._store) + 1,
            owner_id=session.user_id,
            title=meta.title,
            access_level="private"
        )
        serialized = self._serializer.serialize_document(new_meta, content)
        self._store[new_meta.doc_id] = serialized
        return new_meta.doc_id

    def export_document(self, session: UserSession, doc_id: int) -> Optional[bytes]:
        """Export document for backup/transfer."""
        if doc_id not in self._store:
            return None

        meta, content = self._serializer.deserialize_document(self._store[doc_id])

        if not self._check_access(session, meta):
            return None

        return self._store[doc_id]

    def list_shared_documents(self, session: UserSession) -> list:
        """List documents shared with the user."""
        results = []
        for doc_id, raw in self._store.items():
            try:
                meta, _ = self._serializer.deserialize_document(raw)
                if self._check_access(session, meta):
                    results.append(meta)
            except ValueError:
                continue
        return results

    def _check_access(self, session: UserSession, meta: DocumentMeta) -> bool:
        """Verify user has access to the document."""
        if session.role == 'admin':
            return True
        if meta.owner_id == session.user_id:
            return True
        if meta.access_level == 'public':
            return True
        if meta.access_level == 'shared' and 'read_shared' in session.permissions:
            return True
        return False

    def update_access_level(self, session: UserSession, doc_id: int, new_level: str) -> bool:
        """Update document access level. Only owner or admin can do this."""
        if new_level not in ('private', 'shared', 'public'):
            return False

        if doc_id not in self._store:
            return False

        meta, content = self._serializer.deserialize_document(self._store[doc_id])

        # Authorization check: only owner or admin
        if meta.owner_id != session.user_id and session.role != 'admin':
            return False

        updated_meta = DocumentMeta(
            doc_id=meta.doc_id,
            owner_id=meta.owner_id,
            title=meta.title,
            access_level=new_level
        )
        self._store[doc_id] = self._serializer.serialize_document(updated_meta, content)
        return True


def handle_upload_request(store: DocumentStore, user_data: dict, file_bytes: bytes) -> dict:
    """HTTP handler for document upload/import."""
    session = UserSession(
        user_id=user_data['user_id'],
        role=user_data.get('role', 'user'),
        permissions=user_data.get('permissions', [])
    )

    action = user_data.get('action', 'upload')

    if action == 'import':
        doc_id = store.import_document(session, file_bytes)
        if doc_id is None:
            return {'status': 'error', 'message': 'Import failed'}
        return {'status': 'ok', 'doc_id': doc_id}

    elif action == 'upload':
        title = user_data.get('title', 'Untitled')
        doc_id = store.upload_document(session, title, file_bytes)
        return {'status': 'ok', 'doc_id': doc_id}

    elif action == 'export':
        doc_id = user_data.get('doc_id')
        if doc_id is None:
            return {'status': 'error', 'message': 'Missing doc_id'}
        data = store.export_document(session, doc_id)
        if data is None:
            return {'status': 'error', 'message': 'Access denied or not found'}
        return {'status': 'ok', 'data': data.hex()}

    elif action == 'update_access':
        doc_id = user_data.get('doc_id')
        new_level = user_data.get('access_level', 'private')
        if doc_id is None:
            return {'status': 'error', 'message': 'Missing doc_id'}
        success = store.update_access_level(session, doc_id, new_level)
        if not success:
            return {'status': 'error', 'message': 'Update failed'}
        return {'status': 'ok'}

    return {'status': 'error', 'message': 'Unknown action'}
